func capitalizeFirst(s string) string {
	if s == "" {
		return s
	}
	r, size := utf8.DecodeRuneInString(s)
	return string(unicode.ToUpper(r)) + s[size:]
}

func formatSyncStatus(playlist *ent.Playlist) string {
	if playlist.Source == "navidrome" {
		return "Native"
	}
	if playlist.SyncToNavidrome {
		return "Enabled"
	}
	return "Disabled"
}

// formatSyncStatusField returns a human-readable label for the sync_status enum field.
// Governing: SPEC playlist-sync-navidrome REQ-PLSYNC-010 (sync_status state machine)
func formatSyncStatusField(pl *ent.Playlist) string {
	switch string(pl.SyncStatus) {
	case "syncing":
		return "Syncing..."
	case "success":
		return "Fully Synced"
	case "warning":
		return "Partial Sync"
	case "error":
		return "Sync Error"
	case "pending":
		return "Pending"
	default:
		return "Pending"
	}
}

